        final double expected = logFactorial(val);
        Assertions.assertEquals(expected, f2.value(val));
    }

private double logFactorial(final int n) {
        double logSum = 0;
        for (int i = 2; i <= n; i++) {
            logSum += Math.log(i);
        }
        return logSum;
    }

